n}\n\n.empty-state[_ngcontent-%COMP%]   strong[_ngcontent-%COMP%] {\n  display: block;\n\n  margin-bottom: 4px;\n\n  color: var(--text-color);\n  font-size: 14px;\n}\n\n.empty-state[_ngcontent-%COMP%]   span[_ngcontent-%COMP%] {\n  font-size: 12px;\n}\n\n\n\n\n\n\n\n.modal-overlay[_ngcontent-%COMP%] {\n  position: fixed;\n\n  inset: 0;\n\n  display: flex;\n  align-items: center;\n  justify-content: center;\n\n  padding: 20px;\n\n  background: rgba(15, 23, 42, 0.5);\n\n  backdrop-filter: blur(4px);\n\n  z-index: 1000;\n}\n\n.modal-card[_ngcontent-%COMP%] {\n  width: 100%;\n  max-width: 430px;\n\n  max-height: 90vh;\n  overflow-y: auto;\n\n  padding: 28px;\n\n  background: var(--white);\n\n  border-radius: var(--radius-large);\n\n  box-shadow: 0 15px 35px rgba(15, 23, 42, 0.15);\n}\n\n.modal-card[_ngcontent-%COMP%]   h3[_ngcontent-%COMP%] {\n  margin: 0 0 22px;\n\n  color: var(--text-color);\n\n  font-size: 20px;\n}\n\n\n\n\n\n\n\n.form-group[_ngcontent-%COMP%] {\n  margin-bottom: 16px;\n}\n\n.form-group[_ngcontent-%COMP%]   label[_ngcontent-%COMP%] {\n  display: block;\n\n  margin-bottom: 7px;\n\n  color: var(--text-color);\n\n  font-size: 13px;\n}\n\n.form-group[_ngcontent-%COMP%]   input[_ngcontent-%COMP%], .form-group[_ngcontent-%COMP%]   select[_ngcontent-%COMP%] {\n  width: 100%;\n\n  box-sizing: border-box;\n\n  padding: 11px 12px;\n\n  font-size: 14px;\n}\n\n\n\n\n\n\n\n.modal-actions[_ngcontent-%COMP%] {\n  display: flex;\n  justify-content: flex-end;\n\n  gap: 10px;\n\n  margin-top: 25px;\n}\n\n.btn--ghost-dark[_ngcontent-%COMP%] {\n  padding: 10px 16px;\n\n  background: #f1f5f9;\n  color: #475569;\n\n  border-radius: var(--radius-small);\n}\n\n.btn--ghost-dark[_ngcontent-%COMP%]:hover {\n  background: #e2e8f0;\n}\n\n\n\n\n\n\n\n.course-details[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n\n  gap: 13px;\n\n  margin: 20px 0;\n\n  color: #475569;\n\n  font-size: 14px;\n}\n\n.course-details[_ngcontent-%COMP%]   strong[_ngcontent-%COMP%] {\